from shopkit.core.pricing import cashRoundCents

def amount_due(total_cents: int, currency: str, paid_by: str) -> int:
    """Calculate the amount the cashier asks the customer to pay.

    paid_by is "card" or "cash". Card payments pay the exact total;
    cash payments follow national rules for cash amounts (via cashRoundCents).
    """
    if paid_by == "card":
        return total_cents
    elif paid_by == "cash":
        return cashRoundCents(total_cents, currency)
    else:
        raise ValueError(f"Unknown payment method: {paid_by}")
